import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:]]

    b = deque()

    for i in range(n):
        b.append(a[i])
        if i % 2 == 1:
            b.rotate(-1)

    print(" ".join(map(str, b)))

if __name__ == "__main__":
    solve()
